class Solution:
    def mirrorWords(self, s: str) -> str:
        c = list(s)
        start = 0
        while start < len(c):
            end = start
            while end < len(c) and c[end] != " ":
                end += 1
            i, j = start, end - 1
            while i < j:
                c[i], c[j] = c[j], c[i]
                i += 1
                j -= 1
            start = end + 1
        return "".join(c)

