function mirrorWords(s) {
  const c = s.split("");
  let start = 0;
  while (start < c.length) {
    let end = start;
    while (end < c.length && c[end] !== " ") end++;
    let i = start, j = end - 1;
    while (i < j) {
      const t = c[i];
      c[i] = c[j];
      c[j] = t;
      i++;
      j--;
    }
    start = end + 1;
  }
  return c.join("");
}
